import type { DurationContributionMode } from './durationContributionMode.js'

export type V1475CrossItemWorkflowScopeRule =
  | 'same_project'
  | 'same_phase'
  | 'same_building'
  | 'next_floor'
  | 'same_floor'
  | 'same_zone'
  | 'same_system'

export type V1475CrossItemConditionalLagProfile = {
  conditionCode: string
  triggerSignals: string[]
  lagDays: number
  calibrationPolicy: string
}

export type V1475CrossItemWorkflowRule = {
  stableCode: string
  predecessorCodePrefixes: string[]
  successorCodePrefixes: string[]
  excludedPredecessorCodePrefixes?: string[]
  excludedSuccessorCodePrefixes?: string[]
  excludedPredecessorStableCodes?: string[]
  excludedSuccessorStableCodes?: string[]
  predecessorCategoryTypes?: string[]
  successorCategoryTypes?: string[]
  predecessorAnchorDurationContributionModes?: DurationContributionMode[]
  successorAnchorDurationContributionModes?: DurationContributionMode[]
  dependencyType: 'FS' | 'SS' | 'FF' | 'SF'
  lagDays: number
  conditionalLagProfiles?: V1475CrossItemConditionalLagProfile[]
  scopeRule: V1475CrossItemWorkflowScopeRule
  strength: 'hard' | 'recommended' | 'candidate'
  autoApplyPolicy: 'confirmed_template_only' | 'candidate_only' | 'manual_confirm'
  sourceStandard: 'national_standard' | 'industry_standard' | 'system_default' | 'enterprise_method'
  sourceVersion: string
  sourceClauseRef: string
  evidenceSourceKeys: string[]
  boundaryPolicy: string
  rhythmAggregationPolicy?: 'building_level_anchor_no_floor_cartesian_edges'
  managedFrontierProjectionPolicy?: 'item_pack_anchor_when_process_hidden'
  handoffCategory?: V1475CrossItemWorkflowHandoffCategory
  confidence: 'high' | 'medium' | 'low'
  webVerified: true
  reviewNeeded: false
  isActive?: boolean
}

export type V1475CrossItemWorkflowHandoffCategory =
  | 'foundation_deep_basement'
  | 'underground_waterproof_backfill'
  | 'structure_masonry_infill'
  | 'structure_envelope_roof'
  | 'mep_to_finishes'
  | 'mep_system_commissioning'
  | 'fire_life_safety'
  | 'civil_defense_protective_equipment'
  | 'vertical_transport'
  | 'outdoor_municipal'
  | 'smart_building_commissioning'
  | 'data_center_cleanroom'
  | 'prefab_modular'
  | 'renovation_tod'
  | 'hotel_factory_unit'
  | 'mixed_use_interface'
  | 'industrial_production'
  | 'transportation_hub_operation'
  | 'venue_event_handover'

