function slugCode(value: string) {
  return value.toLowerCase().replace(/[^a-z0-9]+/g, '_').replace(/^_+|_+$/g, '')
}

function buildL5FinishReleaseWorkflowRules(options: {
  stableCodePrefix: string
  predecessorCodePrefixes: string[]
  successorCodePrefixes: string[]
  excludedSuccessorCodePrefixes?: string[]
  sourceClauseRef: string
  boundaryPolicy: string
  evidenceSourceKeys?: string[]
  sourceVersionSuffix: string
  handoffCategory?: V1475CrossItemWorkflowHandoffCategory
}): V1475CrossItemWorkflowRule[] {
  return [{
    stableCode: `${options.stableCodePrefix}_existing_edges`,
    predecessorCodePrefixes: options.predecessorCodePrefixes,
    successorCodePrefixes: options.successorCodePrefixes,
    excludedSuccessorCodePrefixes: options.excludedSuccessorCodePrefixes,
    predecessorCategoryTypes: PACKAGE_LEVEL_CATEGORIES,
    successorCategoryTypes: PACKAGE_LEVEL_CATEGORIES,
    dependencyType: 'FS',
    lagDays: 1,
    conditionalLagProfiles: MEP_CLOSURE_TO_FINISH_CONDITIONAL_LAG_PROFILES,
    scopeRule: 'same_floor',
    strength: 'hard',
    autoApplyPolicy: 'confirmed_template_only',
    sourceStandard: 'enterprise_method',
    sourceVersion: `real-project-coverage-20260618 / ${options.sourceVersionSuffix}`,
    sourceClauseRef: options.sourceClauseRef,
    evidenceSourceKeys: options.evidenceSourceKeys ?? ['GB50242_2018', 'GB50243_2016', 'GB50339_2013', 'GB50210_2018', 'GB50300_2013'],
    boundaryPolicy: options.boundaryPolicy,
    handoffCategory: options.handoffCategory ?? 'mep_to_finishes',
    confidence: 'medium',
    webVerified: true,
    reviewNeeded: false,
  }]
}

function buildExactSuccessorL5FinishReleaseWorkflowRules(options: {
  stableCodePrefix: string
  predecessorCodePrefixes: string[]
  successorCodePrefixes: string[]
  sourceClauseRef: string
  boundaryPolicy: string
  evidenceSourceKeys?: string[]
  sourceVersionSuffix: string
  handoffCategory?: V1475CrossItemWorkflowHandoffCategory
}): V1475CrossItemWorkflowRule[] {
  return options.successorCodePrefixes.flatMap((successorCode) => buildL5FinishReleaseWorkflowRules({
    stableCodePrefix: `${options.stableCodePrefix}_${slugCode(successorCode)}`,
    predecessorCodePrefixes: options.predecessorCodePrefixes,
    successorCodePrefixes: [successorCode],
    excludedSuccessorCodePrefixes: options.successorCodePrefixes.filter((candidate) => candidate.startsWith(`${successorCode}-`)),
    sourceClauseRef: options.sourceClauseRef,
    boundaryPolicy: options.boundaryPolicy,
    evidenceSourceKeys: options.evidenceSourceKeys,
    sourceVersionSuffix: options.sourceVersionSuffix,
    handoffCategory: options.handoffCategory,
  }))
}

export const V1475_CROSS_ITEM_BREADTH_EXPANSION_SEED: V1475CrossItemWorkflowRule[] =
  CROSS_ITEM_BREADTH_EXPANSION_GROUPS.flatMap((group) => group.pairs.map(([predecessorCode, successorCode, handoffLabel], index) => {
    const isPrefabFirstBatchRollingRelease = group.category === 'prefab_modular'
      && predecessorCode === 'PFB-00-01-03'
      && successorCode === 'PFB-01-01-01'

    return {
      stableCode: `expanded_${group.category}_${String(index + 1).padStart(2, '0')}_${slugCode(predecessorCode)}_to_${slugCode(successorCode)}`,
      predecessorCodePrefixes: [predecessorCode],
      successorCodePrefixes: [successorCode],
      excludedPredecessorCodePrefixes: group.excludedPredecessorCodePrefixes,
      predecessorCategoryTypes: PACKAGE_LEVEL_CATEGORIES,
      successorCategoryTypes: PACKAGE_LEVEL_CATEGORIES,
      dependencyType: isPrefabFirstBatchRollingRelease ? 'SS' : 'FS',
      lagDays: isPrefabFirstBatchRollingRelease ? 1 : group.lagDays,
      conditionalLagProfiles: group.conditionalLagProfiles,
      scopeRule: group.scopeRule,
      strength: isPrefabFirstBatchRollingRelease ? 'recommended' : 'hard',
      autoApplyPolicy: 'confirmed_template_only',
      sourceStandard: group.sourceStandard,
      sourceVersion: group.sourceVersion ?? V1475_CROSS_ITEM_BREADTH_EXPANSION_SOURCE_VERSION,
      sourceClauseRef: handoffLabel ?? `${predecessorCode} package handoff to ${successorCode}`,
      evidenceSourceKeys: group.evidenceSourceKeys,
      boundaryPolicy: isPrefabFirstBatchRollingRelease
        ? 'Expanded prefab transport-to-first-batch release uses rolling batch handoff semantics; factory transport can release onsite first-batch inspection by start-to-start readiness, while project facts and acceptance records remain final calibration authority.'
        : 'Expanded package-level physical construction handoff only; explicit task dependencies, project facts, scope objects, acceptance facts, and standard duration seeds remain the final calibration authority.',
      handoffCategory: group.category,
      confidence: 'high',
      webVerified: true,
      reviewNeeded: false,
    }
  }))

function specialtyMainlineWorkflowRule(input: {
  stableCode: string
  predecessorCode: string
  successorCode: string
  scopeRule: V1475CrossItemWorkflowScopeRule
  handoffCategory: Extract<
    V1475CrossItemWorkflowHandoffCategory,
    'industrial_production' | 'transportation_hub_operation' | 'venue_event_handover'
  >
  sourceClauseRef: string
  evidenceSourceKeys: string[]
}): V1475CrossItemWorkflowRule {
  return {
    stableCode: input.stableCode,
    predecessorCodePrefixes: [input.predecessorCode],
    successorCodePrefixes: [input.successorCode],
    predecessorCategoryTypes: ['process'],
    successorCategoryTypes: ['process'],
    dependencyType: 'FS',
    lagDays: 1,
    conditionalLagProfiles: [
      {
        conditionCode: `${input.stableCode}_standard_handoff`,
        triggerSignals: ['same_scope_acceptance_record', 'receiving_workface_ready', 'interface_handover_confirmed'],
        lagDays: 1,
        calibrationPolicy: 'Calibrate the standard process-level handoff with completed-project replay, acceptance records, interface handover timestamps, project facts, and duration outcomes.',
      },
      {
        conditionCode: `${input.stableCode}_restricted_or_retest_handoff`,
        triggerSignals: ['restricted_work_window', 'interface_retest_required', 'operator_witness_required'],
        lagDays: 5,
        calibrationPolicy: 'Use project replay, restricted-window facts, retest acceptance, operator witness records, handover evidence, and duration outcomes before applying the stricter process-level buffer.',
      },
    ],
    scopeRule: input.scopeRule,
    strength: 'hard',
    autoApplyPolicy: 'confirmed_template_only',
    sourceStandard: 'enterprise_method',
    sourceVersion: 'specialty-mainline-schedule-trust-process-anchor-20260712',
    sourceClauseRef: input.sourceClauseRef,
    evidenceSourceKeys: input.evidenceSourceKeys,
    boundaryPolicy: `Hard process-level ${input.handoffCategory} interface only; project facts, accepted handover evidence, explicit task dependencies, completed-project replay, and duration calibration remain the final authority for dates and buffers.`,
    managedFrontierProjectionPolicy: 'item_pack_anchor_when_process_hidden',
    handoffCategory: input.handoffCategory,
    confidence: 'high',
    webVerified: true,
    reviewNeeded: false,
  }
}

